using UnityEngine;

public class PersistentManager : MonoBehaviour
{
    public static PersistentManager Instance;

    [Header("Core")]
    public int money = 0;
    public int fishCount = 0;
    public int currentDay = 1;

    [Header("Base Values (Permanent)")]
    public int baseMaxInventory = 10;
    public float baseHookDistance = 10f;
    public float baseHookDamage = 50f;
    public float baseHookSpeed = 5f;

    private void Awake()
    {
        if (Instance != null && Instance != this)
        {
            Destroy(gameObject);
            return;
        }

        Instance = this;
        DontDestroyOnLoad(gameObject);
    }

    public void AddMoney(int amount)
    {
        money += Mathf.Max(0, amount);
    }

    public bool SpendMoney(int amount)
    {
        if (money < amount) return false;
        money -= amount;
        return true;
    }

    public void AddFish(int amount)
    {
        fishCount += Mathf.Max(0, amount);
    }

    public void ResetFish()
    {
        fishCount = 0;
    }
}

using UnityEngine;

public class HookController : MonoBehaviour
{
    [Header("Dönüş ve Görsel Ayarları")]
    public float turnSpeedDegrees = 360f;
    public float spriteRotationOffset = -90f;

    [Header("Ekran Sınırları")]
    public Vector2 minBounds = new Vector2(-15, -10);
    public Vector2 maxBounds = new Vector2(15, 5);

    [Header("İp (Çizim) Ayarları")]
    public LineRenderer lineRenderer;

    public bool isFishing = false;
    private Vector3 currentDirection;

    public void SetFishingMode(bool state)
    {
        isFishing = state;

        if (lineRenderer != null)
        {
            lineRenderer.enabled = state;
            if (state) lineRenderer.positionCount = 2;
        }

        if (isFishing) currentDirection = Vector3.down;
    }

    void Update()
    {
        // YENİ EKLENEN KISIM: Eğer balık tutma modunda değilsek, kanca zorla teknede kalsın!
        if (!isFishing)
        {
            if (FishingManager.Instance != null && FishingManager.Instance.ropeOrigin != null)
            {
                transform.position = FishingManager.Instance.ropeOrigin.position; // Sürekli teknede tut
                transform.rotation = Quaternion.Euler(0, 0, spriteRotationOffset); // İptal olunca düzelt
            }
            return;
        }

        float currentSpeed = FishingManager.Instance.GetCurrentSpeed();
        minBounds.y = FishingManager.Instance.GetCurrentMaxDepth();
        if (FishingManager.Instance.ropeOrigin != null) maxBounds.y = FishingManager.Instance.ropeOrigin.position.y;

        float moveX = Input.GetAxisRaw("Horizontal");
        float moveY = Input.GetAxisRaw("Vertical");
        Vector3 inputDirection = new Vector3(moveX, moveY, 0).normalized;

        if (inputDirection != Vector3.zero)
        {
            float targetAngle = Mathf.Atan2(inputDirection.y, inputDirection.x) * Mathf.Rad2Deg;
            float currentAngle = Mathf.Atan2(currentDirection.y, currentDirection.x) * Mathf.Rad2Deg;
            float nextAngle = Mathf.MoveTowardsAngle(currentAngle, targetAngle, turnSpeedDegrees * Time.deltaTime);
            currentDirection = new Vector3(Mathf.Cos(nextAngle * Mathf.Deg2Rad), Mathf.Sin(nextAngle * Mathf.Deg2Rad), 0);
        }

        Vector3 newPos = transform.position + currentDirection * currentSpeed * Time.deltaTime;
        newPos.x = Mathf.Clamp(newPos.x, minBounds.x, maxBounds.x);
        newPos.y = Mathf.Clamp(newPos.y, minBounds.y, maxBounds.y);
        transform.position = newPos;

        if (currentDirection != Vector3.zero)
        {
            float visualAngle = Mathf.Atan2(currentDirection.y, currentDirection.x) * Mathf.Rad2Deg;
            transform.rotation = Quaternion.Euler(0, 0, visualAngle + spriteRotationOffset);
        }

        UpdateFishingLine();
    }

    private void UpdateFishingLine()
    {
        if (lineRenderer == null || !isFishing) return;
        lineRenderer.SetPosition(0, FishingManager.Instance.ropeOrigin.position);
        lineRenderer.SetPosition(1, transform.position);
    }

    void OnTriggerStay2D(Collider2D other)
    {
        if (!isFishing) return;
        Fish hitFish = other.GetComponent<Fish>();
        if (hitFish != null) hitFish.TakeDamage(FishingManager.Instance.GetCurrentDamage() * Time.deltaTime);
    }
}

using UnityEngine;

public class HookController : MonoBehaviour
{
    [Header("Dönüş ve Görsel Ayarları")]
    public float turnSpeedDegrees = 360f;
    public float spriteRotationOffset = -90f;

    [Header("Ekran Sınırları")]
    public Vector2 minBounds = new Vector2(-15, -10);
    public Vector2 maxBounds = new Vector2(15, 5);

    [Header("İp (Çizim) Ayarları")]
    public LineRenderer lineRenderer;

    [Header("Limits")]
    public float hookTimeLimit = 12f;

    private float hookTimer;

    public bool isFishing = false;
    private Vector3 currentDirection;

    public void SetFishingMode(bool state)
    {
        isFishing = state;
        hookTimer = 0f;

        if (lineRenderer != null)
        {
            lineRenderer.enabled = state;
            if (state) lineRenderer.positionCount = 2;
        }

        if (isFishing) currentDirection = Vector3.down;
    }

    void Update()
    {
        // YENİ EKLENEN KISIM: Eğer balık tutma modunda değilsek, kanca zorla teknede kalsın!
        if (!isFishing)
        {
            if (FishingManager.Instance != null && FishingManager.Instance.ropeOrigin != null)
            {
                transform.position = FishingManager.Instance.ropeOrigin.position; // Sürekli teknede tut
                transform.rotation = Quaternion.Euler(0, 0, spriteRotationOffset); // İptal olunca düzelt
            }
            return;
        }

        hookTimer += Time.deltaTime;
        if (hookTimeLimit > 0f && hookTimer >= hookTimeLimit)
        {
            ReelHook();
            return;
        }

        if (IsInventoryFull())
        {
            ReelHook();
            return;
        }

        float currentSpeed = FishingManager.Instance.GetCurrentSpeed();
        minBounds.y = FishingManager.Instance.GetCurrentMaxDepth();
        if (FishingManager.Instance.ropeOrigin != null) maxBounds.y = FishingManager.Instance.ropeOrigin.position.y;

        float moveX = Input.GetAxisRaw("Horizontal");
        float moveY = Input.GetAxisRaw("Vertical");
        Vector3 inputDirection = new Vector3(moveX, moveY, 0).normalized;

        if (inputDirection != Vector3.zero)
        {
            float targetAngle = Mathf.Atan2(inputDirection.y, inputDirection.x) * Mathf.Rad2Deg;
            float currentAngle = Mathf.Atan2(currentDirection.y, currentDirection.x) * Mathf.Rad2Deg;
            float nextAngle = Mathf.MoveTowardsAngle(currentAngle, targetAngle, turnSpeedDegrees * Time.deltaTime);
            currentDirection = new Vector3(Mathf.Cos(nextAngle * Mathf.Deg2Rad), Mathf.Sin(nextAngle * Mathf.Deg2Rad), 0);
        }

        Vector3 newPos = transform.position + currentDirection * currentSpeed * Time.deltaTime;
        newPos.x = Mathf.Clamp(newPos.x, minBounds.x, maxBounds.x);
        newPos.y = Mathf.Clamp(newPos.y, minBounds.y, maxBounds.y);
        transform.position = newPos;

        if (currentDirection != Vector3.zero)
        {
            float visualAngle = Mathf.Atan2(currentDirection.y, currentDirection.x) * Mathf.Rad2Deg;
            transform.rotation = Quaternion.Euler(0, 0, visualAngle + spriteRotationOffset);
        }

        UpdateFishingLine();
    }

    private bool IsInventoryFull()
    {
        if (PersistentManager.Instance == null || DayManager.Instance == null) return false;
        int maxInv = DayManager.Instance.GetFinalMaxInventory();
        return PersistentManager.Instance.fishCount >= maxInv;
    }

    private void ReelHook()
    {
        SetFishingMode(false);
        if (FishingManager.Instance != null && FishingManager.Instance.ropeOrigin != null)
        {
            transform.position = FishingManager.Instance.ropeOrigin.position;
        }
    }

    private void UpdateFishingLine()
    {
        if (lineRenderer == null || !isFishing) return;
        lineRenderer.SetPosition(0, FishingManager.Instance.ropeOrigin.position);
        lineRenderer.SetPosition(1, transform.position);
    }

    void OnTriggerStay2D(Collider2D other)
    {
        if (!isFishing) return;
        Fish hitFish = other.GetComponent<Fish>();
        if (hitFish != null) hitFish.TakeDamage(FishingManager.Instance.GetCurrentDamage() * Time.deltaTime);
    }
}

using System.Collections;
using UnityEngine;
using TMPro;

public class ShopUIManager : MonoBehaviour
{
    [Header("UI")]
    public TextMeshProUGUI moneyText;
    public TextMeshProUGUI warningText;

    [Header("Permanent Upgrade Costs")]
    public int damageUpgradeCost = 100;
    public int distanceUpgradeCost = 100;
    public int speedUpgradeCost = 120;
    public int inventoryUpgradeCost = 150;

    [Header("Permanent Upgrade Increments")]
    public float damageUpgradeAmount = 10f;
    public float distanceUpgradeAmount = 1f;
    public float speedUpgradeAmount = 0.5f;
    public int inventoryUpgradeAmount = 1;

    [Header("Buff Costs")]
    public int damageBuffCost = 80;
    public int distanceBuffCost = 80;
    public int speedBuffCost = 80;
    public int inventoryBuffCost = 80;

    [Header("Buff Increments")]
    public float damageBuffMultiplier = 0.1f;
    public float distanceBuffMultiplier = 0.1f;
    public float speedBuffAmount = 0.5f;
    public float inventoryBuffMultiplier = 0.1f;

    private Coroutine _warningRoutine;

    private void OnEnable()
    {
        UpdateUI();
    }

    public void UpdateUI()
    {
        if (moneyText != null && PersistentManager.Instance != null)
        {
            moneyText.text = "Para: " + PersistentManager.Instance.money + "$";
        }
    }

    public void BuyDamageUpgrade()
    {
        if (!TrySpend(damageUpgradeCost)) return;
        if (PersistentManager.Instance != null) PersistentManager.Instance.baseHookDamage += damageUpgradeAmount;
        UpdateUI();
    }

    public void BuyDistanceUpgrade()
    {
        if (!TrySpend(distanceUpgradeCost)) return;
        if (PersistentManager.Instance != null) PersistentManager.Instance.baseHookDistance += distanceUpgradeAmount;
        UpdateUI();
    }

    public void BuySpeedUpgrade()
    {
        if (!TrySpend(speedUpgradeCost)) return;
        if (PersistentManager.Instance != null) PersistentManager.Instance.baseHookSpeed += speedUpgradeAmount;
        UpdateUI();
    }

    public void BuyInventoryUpgrade()
    {
        if (!TrySpend(inventoryUpgradeCost)) return;
        if (PersistentManager.Instance != null) PersistentManager.Instance.baseMaxInventory += inventoryUpgradeAmount;
        UpdateUI();
    }

    public void BuyDamageBuff()
    {
        if (!TrySpend(damageBuffCost)) return;
        if (DayManager.Instance != null) DayManager.Instance.damageMultiplier += damageBuffMultiplier;
        UpdateUI();
    }

    public void BuyDistanceBuff()
    {
        if (!TrySpend(distanceBuffCost)) return;
        if (DayManager.Instance != null) DayManager.Instance.distanceMultiplier += distanceBuffMultiplier;
        UpdateUI();
    }

    public void BuySpeedBuff()
    {
        if (!TrySpend(speedBuffCost)) return;
        if (DayManager.Instance != null) DayManager.Instance.speedBuff += speedBuffAmount;
        UpdateUI();
    }

    public void BuyInventoryBuff()
    {
        if (!TrySpend(inventoryBuffCost)) return;
        if (DayManager.Instance != null) DayManager.Instance.inventoryMultiplier += inventoryBuffMultiplier;
        UpdateUI();
    }

    private bool TrySpend(int cost)
    {
        if (PersistentManager.Instance == null) return false;

        if (PersistentManager.Instance.SpendMoney(cost)) return true;

        ShowWarning();
        return false;
    }

    public void ShowWarning()
    {
        if (warningText == null) return;

        if (_warningRoutine != null) StopCoroutine(_warningRoutine);
        _warningRoutine = StartCoroutine(WarningRoutine());
    }

    private IEnumerator WarningRoutine()
    {
        warningText.gameObject.SetActive(true);
        warningText.text = "Yetersiz Bakiye!";
        yield return new WaitForSeconds(2f);
        warningText.gameObject.SetActive(false);
    }
}

using System.Collections;
using UnityEngine;
using UnityEngine.SceneManagement;
using TMPro;

public class TownManager : MonoBehaviour
{
    public enum TownZone { None, Sell, Upgrade, Home }

    [Header("Triggers")]
    public Collider2D sellTrigger;
    public Collider2D upgradeTrigger;
    public Collider2D homeTrigger;

    [Header("Panels")]
    public GameObject sellPanel;
    public GameObject upgradePanel;
    public GameObject homePanel;

    [Header("Prompts")]
    public GameObject sellPrompt;
    public GameObject upgradePrompt;
    public GameObject homePrompt;

    [Header("Home UI")]
    public CanvasGroup fadeGroup;
    public TextMeshProUGUI dayText;
    public float fadeDuration = 0.6f;

    private TownZone _currentZone = TownZone.None;

    private void Update()
    {
        if (_currentZone == TownZone.None) return;

        if (Input.GetKeyDown(KeyCode.E))
        {
            if (_currentZone == TownZone.Sell)
            {
                OpenPanel(sellPanel);
                SellAllFish();
            }
            else if (_currentZone == TownZone.Upgrade)
            {
                OpenPanel(upgradePanel);
            }
            else if (_currentZone == TownZone.Home)
            {
                StartCoroutine(EndDayRoutine());
            }
        }
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        if (!other.CompareTag("Player")) return;

        if (sellTrigger != null && other.IsTouching(sellTrigger))
        {
            _currentZone = TownZone.Sell;
            SetPrompt(sellPrompt, true);
        }
        else if (upgradeTrigger != null && other.IsTouching(upgradeTrigger))
        {
            _currentZone = TownZone.Upgrade;
            SetPrompt(upgradePrompt, true);
        }
        else if (homeTrigger != null && other.IsTouching(homeTrigger))
        {
            _currentZone = TownZone.Home;
            SetPrompt(homePrompt, true);
        }
    }

    private void OnTriggerExit2D(Collider2D other)
    {
        if (!other.CompareTag("Player")) return;

        if (sellTrigger != null && other.IsTouching(sellTrigger) == false)
        {
            SetPrompt(sellPrompt, false);
        }
        if (upgradeTrigger != null && other.IsTouching(upgradeTrigger) == false)
        {
            SetPrompt(upgradePrompt, false);
        }
        if (homeTrigger != null && other.IsTouching(homeTrigger) == false)
        {
            SetPrompt(homePrompt, false);
        }

        _currentZone = TownZone.None;
    }

    private void SetPrompt(GameObject prompt, bool active)
    {
        if (prompt != null) prompt.SetActive(active);
    }

    private void OpenPanel(GameObject panel)
    {
        if (panel == null) return;
        panel.SetActive(true);
    }

    private void SellAllFish()
    {
        if (PersistentManager.Instance == null) return;

        int earnings = PersistentManager.Instance.fishCount * 10;
        PersistentManager.Instance.AddMoney(earnings);
        PersistentManager.Instance.ResetFish();
    }

    private IEnumerator EndDayRoutine()
    {
        if (fadeGroup != null)
        {
            fadeGroup.gameObject.SetActive(true);
            yield return FadeCanvas(0f, 1f, fadeDuration);
        }

        if (PersistentManager.Instance != null)
        {
            PersistentManager.Instance.currentDay += 1;
        }

        if (dayText != null && PersistentManager.Instance != null)
        {
            dayText.text = "G\u00fcn: " + PersistentManager.Instance.currentDay;
        }

        yield return new WaitForSeconds(0.8f);

        Scene currentScene = SceneManager.GetActiveScene();
        SceneManager.LoadScene(currentScene.name);
    }

    private IEnumerator FadeCanvas(float from, float to, float duration)
    {
        float timer = 0f;
        while (timer < duration)
        {
            timer += Time.deltaTime;
            float t = Mathf.Clamp01(timer / duration);
            if (fadeGroup != null) fadeGroup.alpha = Mathf.Lerp(from, to, t);
            yield return null;
        }
        if (fadeGroup != null) fadeGroup.alpha = to;
    }
}
